function evidence = f90_xtherm07_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XTHERM07_EXTRACT_CANDIDATE_EVIDENCE Public-contract candidate adapter.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XTHERM-07");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xtherm07-evidence.v1", ...
    "task_id", "F90-XTHERM-07", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localInputs, ...
    "stop_time", @(~, ~) double(official.simulation.stop_s), ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "evidence_sample_s", 10.0);
evidence = simuverity_run_candidate_evidence( ...
    candidatePath, outDir, spec);
end

function rows = localOutputs
rows = localRows(["thermal_state","fan_state","heat_flow"], [4 3 4]);
end

function inputs = localInputs(scenario, ~)
inputs = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, ~, ~)
row.outputs = outputs;
row.valid = row.output_contract.all_required_pass;
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = structure.semantic_types;
thermalMass = nnz(contains(semantic, ["thermal mass","thermal capacitance"]));
conductive = nnz(contains(semantic, ["conductive heat","conduction"]));
gasPipe = nnz(contains(semantic, ["pipe (g)","gas pipe"]));
gasResistance = nnz(contains(semantic, ...
    ["local restriction","flow resistance","orifice"]));
fan = nnz(contains(semantic, ["fan (g)","fan"]));
core = structure.connected_output_count == numel(spec.output_contract) && ...
    structure.nontrivial_output_source_count == ...
        numel(spec.output_contract) && ...
    structure.physical_connection_block_count >= 4 && ...
    thermalMass >= 1 && conductive >= 1 && fan >= 1;
audit = struct( ...
    "thermal_mass_count", thermalMass, ...
    "conductive_path_count", conductive, ...
    "gas_pipe_count", gasPipe, ...
    "gas_resistance_count", gasResistance, ...
    "physical_fan_count", fan, ...
    "connected_public_output_count", structure.connected_output_count, ...
    "core_path_qualified", core);
end

function rows = localRows(names, widths)
rows = repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name=names(k); rows(k).evidence_name=names(k);
    rows(k).width=widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath")); tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared"); repoRoot=tasksRoot;
for k=1:3, repoRoot=fileparts(repoRoot); end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
end
